{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Fimasartan, the closest ARB analogue by Morgan similarity, has an absolute oral bioavailability of 18.6% in healthy subjects, below the 20% threshold; its shared imidazole/butyl/N-benzyl ARB scaffold and acidic character support a low-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Telmisartan shows 57.4% absolute bioavailability, which would support high F, but its benzimidazole/biphenyl-carboxylate scaffold is less transferable to the query's dicarboxylic acid, zwitterionic eprosartan-like structure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Irbesartan shows 82% oral bioavailability, another high-F ARB, but its spiro/tetrazole scaffold and higher lipophilicity are not representative of the query's two-carboxylate polar structure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is eprosartan, a dicarboxylic acid ARB with zwitterionic character and known low oral bioavailability. The closest supplied analogue, fimasartan, has F=18.6%, below the 20% threshold, and the additional polar carboxylate groups in the query support even lower permeability/first-pass behavior. High-F ARBs such as telmisartan and irbesartan are structurally less transferable and do not override the low-F evidence.",
  "evidence_gaps": [
    "No direct eprosartan absolute bioavailability record is present in the supplied evidence; direct human F data for eprosartan would be definitive.",
    "The supplied analogues have low Morgan similarity scores, so structural transfer is based on ARB-class and physicochemical reasoning rather than close scaffold identity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

